
from selenium import webdriver
from selenium.webdriver.chrome.options import Options
from helper import SCREENSHOTS_DIR 

def before_all(context):
    # Create the screenshots folder if it does not exist
    SCREENSHOTS_DIR.mkdir(exist_ok=True)
    # Delete screenshots generated by previous test runs
    for screenshot in SCREENSHOTS_DIR.glob("*.png"):
        screenshot.unlink()
    # Initialise the screenshot counter
    context.screenshot_data = {"counter": 0}

def before_scenario(context, scenario):
    options = Options()
    options.add_argument("--window-size=1440,900") # We adjust the window size in order to make sure that the Desktop dropdown menu is visible
    context.driver = webdriver.Chrome(options=options) # We have to pass the argument options to the driver to apply the custom settings

def after_scenario(context, scenario):
    driver = getattr(context, "driver", None)
    if driver:
        try:
            # Increase the screenshot counter
            context.screenshot_data["counter"] += 1

            # Generate the screenshot filename
            number = context.screenshot_data["counter"]
            filename = f"scenario_{number}.png"

            # Save the screenshot
            screenshot_path = SCREENSHOTS_DIR / filename
            driver.save_screenshot(str(screenshot_path))

        finally:
            driver.quit()
    
